{
  "description": "The creature is shown in left-facing side profile against a plain light background. It has the overall body shape, fur, head, legs, hooves and short tail of a shaggy brown goat, but with a large domed tortoise-like shell fused to its mid-back covering from the shoulders to the rump, and with overlapping armored scutes covering parts of all four legs. The fur is long and shaggy, darker brown on the back and neck with a lighter cream underbelly, and the shell and leg armor are brown, tan and black with raised, ridged scutes.",
  "parts": [
    {
      "part": "head",
      "looks_like": "goat-like head in left profile with a narrow muzzle, dark nose, closed mouth, visible light brown eye, and a small pointed beard under the chin, covered in shaggy brown fur",
      "where": "at the front left end of the body on top of the neck"
    },
    {
      "part": "horns",
      "looks_like": "two thick, ridged, curved horns, brown with growth rings, tapering to a blunt point and curving backward then forward",
      "where": "on top of the head behind the forehead, one slightly behind the other"
    },
    {
      "part": "ears",
      "looks_like": "two small, pointed, upright ears with visible inner fur detail",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane",
      "looks_like": "long, shaggy, wavy brown fur, thicker and darker on the neck and chest forming a mane and beard, lighter tan on the belly and flanks",
      "where": "along the neck, chest, sides and underside of the body"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, goat-like legs covered in brown fur with large overlapping dark brown armored scutes on the upper and lower segments",
      "where": "beneath the body, two front legs under the chest and two hind legs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four cloven hooves with dark keratin and fur-covered pasterns above",
      "where": "at the bottom tip of each leg touching the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, fluffy tuft of shaggy brown hair",
      "where": "at the rear right end of the body just below and behind the shell"
    },
    {
      "part": "wings",
      "looks_like": "not visible",
      "where": "none"
    },
    {
      "part": "gills",
      "looks_like": "not visible",
      "where": "none"
    },
    {
      "part": "tentacles",
      "looks_like": "not visible",
      "where": "none"
    },
    {
      "part": "shell",
      "looks_like": "large, high-domed carapace with raised pyramidal scutes in banded brown, tan and black with concentric growth lines and a keeled midline, with a flared serrated edge",
      "where": "fused to the dorsal mid-back covering from behind the shoulders to above the hips"
    },
    {
      "part": "plates",
      "looks_like": "overlapping, thick, dark brown scute plates with ridged, layered texture",
      "where": "on the front and hind legs covering the thigh, knee and shin areas in patches"
    },
    {
      "part": "scales",
      "looks_like": "scale-like scutes forming the shell and leg armor, with textured concentric ridges",
      "where": "on the back as the shell and on all four legs as armor patches"
    },
    {
      "part": "feathers",
      "looks_like": "not visible",
      "where": "none"
    },
    {
      "part": "markings",
      "looks_like": "overall brown coat with lighter cream on the belly and inner legs, a thin dark stripe from the eye toward the muzzle, and contrasting light and dark banding on the shell scutes",
      "where": "on the face, body fur and shell"
    }
  ],
  "attached_objects": [],
  "animals": [
    "goat",
    "tortoise"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
